#include <stdarg.h>
#include <stdlib.h>

#include "windef.h"
#include "winbase.h"
#include "winuser.h"
#include "ntuser.h"
#include "ntuser_private.h"
#include "wine/debug.h"

WINE_DEFAULT_DEBUG_CHANNEL(darkmode);

/* undocumented preferred app modes (uxtheme ordinal 135) */
enum preferred_app_mode
{
    PAM_DEFAULT     = 0,
    PAM_ALLOW_DARK  = 1,
    PAM_FORCE_DARK  = 2,
    PAM_FORCE_LIGHT = 3,
};

static int app_mode = PAM_DEFAULT;

/* per-window dark mode overrides set by AllowDarkModeForWindow */
enum window_dark_state
{
    WDS_NONE     = 0,  /* no override, use the app mode */
    WDS_ALLOW    = 1,
    WDS_DISALLOW = 2,
};

struct dark_window
{
    HWND hwnd;
    int state;
};

static struct dark_window *dark_windows;
static unsigned int dark_windows_count;
static unsigned int dark_windows_size;

static int get_window_state( HWND hwnd )
{
    unsigned int i;

    for (i = 0; i < dark_windows_count; i++)
        if (dark_windows[i].hwnd == hwnd) return dark_windows[i].state;
    return WDS_NONE;
}

static void set_window_state( HWND hwnd, int state )
{
    unsigned int i;

    for (i = 0; i < dark_windows_count; i++)
    {
        if (dark_windows[i].hwnd == hwnd)
        {
            dark_windows[i].state = state;
            return;
        }
    }

    if (!state) return;

    if (dark_windows_count == dark_windows_size)
    {
        unsigned int new_size = dark_windows_size ? dark_windows_size * 2 : 16;
        struct dark_window *new_windows = realloc( dark_windows, new_size * sizeof(*new_windows) );

        if (!new_windows) return;
        dark_windows = new_windows;
        dark_windows_size = new_size;
    }

    dark_windows[dark_windows_count].hwnd = hwnd;
    dark_windows[dark_windows_count].state = state;
    dark_windows_count++;
}

/* called when a window is destroyed */
void darkmode_remove_window( HWND hwnd )
{
    unsigned int i;

    for (i = 0; i < dark_windows_count; i++)
    {
        if (dark_windows[i].hwnd == hwnd)
        {
            dark_windows[i] = dark_windows[--dark_windows_count];
            return;
        }
    }
}

