{
    int previous = app_mode;

    TRACE( "%d\n", mode );

    if (mode < PAM_DEFAULT || mode > PAM_FORCE_LIGHT) return previous;
    app_mode = mode;
    return previous;
}

/**********************************************************************
 *           NtUserAllowDarkModeForWindow    (win32u.@)
 */
BOOL WINAPI NtUserAllowDarkModeForWindow( HWND hwnd, BOOL allow )
{
    TRACE( "%p %d\n", hwnd, allow );

    if (!is_window( hwnd )) return FALSE;
    set_window_state( hwnd, allow ? WDS_ALLOW : WDS_DISALLOW );
    return TRUE;
}

/**********************************************************************
 *           NtUserIsDarkModeAllowedForWindow    (win32u.@)
 */
BOOL WINAPI NtUserIsDarkModeAllowedForWindow( HWND hwnd )
{
    TRACE( "%p\n", hwnd );

