/* Window property used to mark a window as using dark mode.  The value is 1
 * for dark and 2 for explicitly light; the property is absent when unset.
 * DwmSetWindowAttribute(DWMWA_USE_IMMERSIVE_DARK_MODE) and AllowDarkModeForWindow
 * both set it, and win32u uses it to decide whether to draw a dark menu bar. */
#define DARK_MODE_PROP L"__wine_dark_mode"

static BOOL CALLBACK mark_dark_window( HWND hwnd, LPARAM lparam )
{
    DWORD pid;

    GetWindowThreadProcessId( hwnd, &pid );
    if (pid == GetCurrentProcessId())
        SetPropW( hwnd, DARK_MODE_PROP, lparam ? (HANDLE)1 : NULL );
    return TRUE;
}

void WINAPI RefreshImmersiveColorPolicyState(void)
{
    /* nothing to do, dark mode is tracked per window */
}

